USE cert_roi_latam;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
-- Copia persistente del texto previo; no se sobreescribe al repetir.
IF OBJECT_ID('dbo.respaldo_texto_v1','U') IS NULL
 SELECT vacante_id,titulo,descripcion INTO dbo.respaldo_texto_v1 FROM dbo.fact_vacantes;
IF OBJECT_ID('dbo.cert_evidencia_v2','U') IS NULL
 CREATE TABLE dbo.cert_evidencia_v2 (
 vacante_id BIGINT NOT NULL, codigo VARCHAR(50) NOT NULL,
 alias NVARCHAR(200) NOT NULL, estado VARCHAR(30) NOT NULL,
 precision VARCHAR(30) NOT NULL, evidencia NVARCHAR(MAX) NOT NULL);
-- Se conserva fact_vacante_cert como resultado historico para comparar.

UPDATE dbo.fact_vacantes SET titulo=N'Revenue Operations Manager', descripcion=N'<h3>What you bring</h3><ul><li>A degree in business, engineering, economics, data analytics or a related field.</li><li>5+ years in revenue operations, sales operations or commercial analytics, ideally in B2B SaaS or subscriptions.</li><li>At least 3 years managing people, with a track record of leading, coaching and developing teams.</li><li>Advanced Salesforce knowledge: reports, dashboards, data models and data governance.</li><li>Hands-on experience with Clari, Outreach, Dialpad, Kombo, Sales Navigator or close equivalents.</li><li>A working command of subscription sales metrics.</li><li>Advanced Excel or Google Sheets, plus SQL or SOQL.</li><li>Practical experience building with AI tools.</li><li>Strong planning and priority-setting skills</li><li>The ability to turn analysis into a clear story for senior management.</li><li>Fluent English and Spanish.</li></ul><h3>Funciones</h3><ul><li>Own New Sales and Renewals forecasting, reporting current performance and the outlook for the next two quarters.</li><li>Track and explain the core sales metrics: stage conversion, pipeline coverage, win rate, GRR, NRR and forecast accuracy.</li><li>Build clear dashboards and presentations for senior management and the board.</li><li>Own the end-to-end sales process and the renewals client journey, including stage gates, handovers and onboarding.</li><li>Enforce pipeline hygiene and CRM data quality.</li><li>Manage lead generation quality, measured by conversion to Closed Won.</li><li>Drive the commercial tech stack: Salesforce, Clari, Outreach, Dialpad, Kombo and LinkedIn Sales Navigator.</li><li>Build AI tools in Claude on top of our Salesforce, platform and product usage data, using MCP connectors.</li><li>Lead, coach and develop a team of three: Sales Operations Analyst, Lead Generation lead and Salesforce Administrator.</li></ul><h3>Deseable</h3><ul><li>Salesforce Administrator or RevOps certification.</li><li>Experience building AI tools on company data (MCP, APIs, agent workflows).</li><li>Experience with lead scoring, routing and attribution models.</li><li>Knowledge of Latin American markets or BNamericas'' sectors.</li><li>Portuguese.</li></ul><h3>Beneficios</h3>' WHERE url_vacante=N'https://www.getonbrd.com/jobs/revenue-operations-manager-bnamericas-remote' AND fuente_id IN (SELECT fuente_id FROM dbo.dim_fuente WHERE nombre='GetOnBoard');
DELETE e FROM dbo.cert_evidencia_v2 e JOIN dbo.fact_vacantes v ON v.vacante_id=e.vacante_id WHERE url_vacante=N'https://www.getonbrd.com/jobs/revenue-operations-manager-bnamericas-remote' AND fuente_id IN (SELECT fuente_id FROM dbo.dim_fuente WHERE nombre='GetOnBoard');
UPDATE dbo.fact_vacantes SET titulo=N'Business Analyst (E-commerce & Digital)', descripcion=N'<h3>Requisitos excluyentes</h3><ul><li>Al menos 2 años de experiencia como Business Analyst.</li><li>Experiencia redactando historias de usuario, documentación funcional y criterios de aceptación, y modelando flujos BPMN y casos de uso, con Jira y Confluence.</li><li>Experiencia participando en pruebas QA, UAT y validación en producción.</li><li>Experiencia trabajando con metodologías ágiles (squads, Product Owners, ceremonias, backlog y releases).</li><li>Manejo de Excel avanzado.</li><li>Experiencia en contextos digitales (ecommerce, medios de pago, marketing digital o productos digitales) y en contacto directo con áreas de negocio.</li><li>Alta capacidad de comunicación y perfil orientado a la gestión y al relacionamiento con múltiples stakeholders.</li><li>Residir en Santiago, Chile, y disponibilidad para modalidad híbrida, con asistencia de 1 a 2 días a la semana a la oficina en Alto Las Condes.</li></ul><h3>Funciones</h3><ul><li>Levantar requerimientos a través de entrevistas, workshops y reuniones con áreas comerciales, marketing, operaciones, finanzas y TI.</li><li>Traducir necesidades de negocio en historias de usuario claras, documentación funcional y criterios de aceptación, usando Jira y Confluence.</li><li>Modelar procesos en flujos BPMN y documentar casos de uso, apoyándote en herramientas como Miro.</li><li>Construir y mantener un backlog priorizado, negociando alcance, tiempos y prioridades con negocio y con los equipos técnicos.</li><li>Participar en las pruebas QA, UAT y validación en producción, asegurando que las funcionalidades se implementen como fueron definidas.</li><li>Coordinar y dar seguimiento a iniciativas digitales: avances, riesgos, dependencias y cierres con impacto medible.</li><li>Revisar métricas clave (ventas, funnels, campañas, comportamiento digital, recurrencia) junto a data/BI, con apoyo de Excel avanzado, para proponer mejoras y medir el desempeño con los KPI correctos.</li></ul><h3>Deseable</h3><ul><li>Título de Ingeniería Civil Industrial o Ingeniería Industrial.</li><li>Experiencia con Miro y uso de Claude u otras herramientas de IA generativa en el trabajo diario.</li><li>Inglés.</li><li>Experiencia en proyectos de retail, omnicanalidad o fidelización.</li><li>Conocimiento de métricas de ecommerce y marketing digital (conversión, ticket promedio, recurrencia, performance de campañas).</li><li>Experiencia como Business Analyst o Product Analyst en empresas grandes.</li></ul><h3>Beneficios</h3><p>En WiTi promovemos un ambiente colaborativo donde el aprendizaje continuo es parte fundamental. Entre nuestros beneficios:</p><ul><li>Plan de carrera personalizado.</li><li>Certificaciones.</li><li>Cursos de idiomas.</li><li>Modalidad híbrida: 1 a 2 días a la semana en oficina en Alto Las Condes (Santiago).</li><li>Jornada de lunes a viernes en horario de oficina.</li></ul>' WHERE url_vacante=N'https://www.getonbrd.com/jobs/business-analyst-ecommerce-digital-witi-santiago' AND fuente_id IN (SELECT fuente_id FROM dbo.dim_fuente WHERE nombre='GetOnBoard');
DELETE e FROM dbo.cert_evidencia_v2 e JOIN dbo.fact_vacantes v ON v.vacante_id=e.vacante_id WHERE url_vacante=N'https://www.getonbrd.com/jobs/business-analyst-ecommerce-digital-witi-santiago' AND fuente_id IN (SELECT fuente_id FROM dbo.dim_fuente WHERE nombre='GetOnBoard');
UPDATE dbo.fact_vacantes SET titulo=N'Snowflake Data Engineer', descripcion=N'<h3>Skills & Education/Experience</h3><p>We are looking for a Data Engineer with strong experience on <b>Snowflake</b> and <b>dbt</b>, primarily working on <b>AWS</b> cloud platforms. The main function of this role is to support specialized utility programs by leveraging software packages and data warehouses used in the Direct Procurement functional area.</p><p><b>Required skills and capabilities</b></p><ul><li>Verbal and written communication skills, problem solving skills, customer service, and strong interpersonal skills.</li><li>Ability to work independently and manage one’s time.</li><li>Basic mentoring skills to provide support and constructive performance feedback.</li><li>Thorough knowledge of the <b>SDLC (Software Development Life Cycle)</b> process and IT controls.</li><li>Expertise with <b>Snowflake</b>, <b>dbt</b>, <b>DataStage</b>, <b>PL/SQL</b>, <b>Oracle</b>, and <b>IBM Mainframe</b>.</li></ul><p><b>Education and experience</b></p><ul><li>Bachelor’s degree in computer science or equivalent training required.</li><li>7+ years of related experience required.</li></ul><h3>Funciones</h3>We support specialized utility programs using software packages and data warehouses for the Direct Procurement functional area. A typical analyst is responsible for supporting and enhancing software for client use to optimize operational efficiency for procurement functions. <ul><li>Support applications and data warehouses from a daily operations perspective.</li><li>Manage user access requests to applications and data warehouses.</li><li>Test and deploy minor enhancements, bug fixes, and forced changes for supported applications and data warehouses.</li><li>Coordinate software system installation and upgrades with offshore teams to meet desired business or IT outcomes.</li><li>Analyze information to determine, recommend, and plan computer specifications and layouts.</li><li>Obtain and evaluate information on reporting formats, costs, and security needs to determine hardware configuration.</li><li>Consult with customers about requirements, system changes, and training needs.</li><li>Coordinate with systems analysts, engineers, programmers, and others to design systems and gather information on project limitations, capabilities, performance requirements, and interfaces.</li></ul><h3>Deseable</h3><ul><li>Experience supporting end-to-end data warehouse operations (daily support, access management, and incident resolution).</li><li>Hands-on experience testing and deploying minor enhancements, bug fixes, and forced changes.</li><li>Experience coordinating installations and upgrades with offshore teams.</li><li>Strong understanding of security needs and hardware configuration planning for reporting and data workloads.</li><li>Comfort partnering with customers and cross-functional teams on requirements, system changes, and training needs.</li></ul><h3>Beneficios</h3><p>We will tailor the work setup to the client needs within <b>Colombia or Chile</b> localization. If you’re an <b>SAP FICO</b> professional who enjoys ownership, continuous improvement, and supporting finance operations, we’d like to meet you.</p>' WHERE url_vacante=N'https://www.getonbrd.com/jobs/snowflake-data-engineer-crest-it-resources-llc-remote' AND fuente_id IN (SELECT fuente_id FROM dbo.dim_fuente WHERE nombre='GetOnBoard');
